UPDATE `tblpackages` SET `Description` = 'Your driver tracks your flight and waits in arrivals with a name board, then takes you straight to your hotel or home in Kathmandu, Lalitpur or Bhaktapur. Drop-offs are timed so you reach the terminal with room to spare.' WHERE `id` = 1;
UPDATE `tblpackages` SET `Description` = 'Land in Pokhara and head to Lakeside, or fly into Bhairahawa and go straight on to Lumbini. The price is fixed, so there\'s no haggling at the terminal.' WHERE `id` = 2;
UPDATE `tblpackages` SET `Description` = 'Book a clean, air-conditioned car for a single trip across town, whether it\'s a meeting, a hospital visit or a family dinner. The fare is agreed upfront and there\'s no meter.' WHERE `id` = 3;
UPDATE `tblpackages` SET `Description` = 'Set your own stops and the driver waits while you finish each one. It suits a busy half day around the valley.' WHERE `id` = 4;
UPDATE `tblpackages` SET `Description` = 'Plan meetings, family visits or a shopping run without worrying about taxis or parking. The driver stays with you from morning to evening.' WHERE `id` = 5;
UPDATE `tblpackages` SET `Description` = 'See the temples, stupas and royal squares that define Kathmandu, with a driver who knows the shortcuts and the best parking. You set the pace at each site.' WHERE `id` = 6;
UPDATE `tblpackages` SET `Description` = 'You\'re picked up before dawn and reach the ridge in time for sunrise over the mountains. On the way back you stop at the valley\'s oldest temple and are home before lunch.' WHERE `id` = 7;
UPDATE `tblpackages` SET `Description` = 'Drive along the Trishuli river to Kurintar, ride the cable car up to the hilltop temple for darshan, and be back in Kathmandu by evening. It works well for families with elders.' WHERE `id` = 8;
UPDATE `tblpackages` SET `Description` = 'Take the scenic Prithvi Highway with a tea stop in Bandipur. Spend a day on Sarangkot, the caves, the waterfalls and Phewa Lake, then drive home at your own pace.' WHERE `id` = 9;
UPDATE `tblpackages` SET `Description` = 'Drive down to the edge of Chitwan National Park and keep the car on standby for local outings while you do your safari. You head back to Kathmandu on the third day.' WHERE `id` = 10;
UPDATE `tblpackages` SET `Description` = 'Stroll the old bazaar and catch the Himalayan sunset from Tundikhel. The next morning, explore a cave or nearby village before driving home.' WHERE `id` = 11;
UPDATE `tblpackages` SET `Description` = 'Arrive in Lumbini in time for a quiet evening at the Maya Devi Temple. Spend a full day among the international monasteries, then visit the ancient palace ruins at Tilaurakot on the way home.' WHERE `id` = 12;
UPDATE `tblpackages` SET `Description` = 'Take the BP Highway down to Mithila country for darshan at Janaki Mandir, Ram Mandir and the sacred ponds. The trip includes an evening at the aarati.' WHERE `id` = 13;
UPDATE `tblpackages` SET `Description` = 'An experienced mountain driver takes you from Pokhara through Jomsom and Kagbeni for darshan at Muktinath. You stay overnight in apple-growing Marpha on the way down.' WHERE `id` = 14;
UPDATE `tblpackages` SET `Description` = 'Arrive in style with floral decoration and a driver who keeps to your programme. Convoys and premium decoration are available on request.' WHERE `id` = 15;
UPDATE `tblpackages` SET `Description` = 'Cover staff commutes, client visits and airport runs with a single monthly contract. Maintenance, insurance and a replacement car are all handled by Rento.' WHERE `id` = 16;
